/* test_knsrtp.c — known-answer tests for SRTP crypto phase 1 (kn_aes + knsrtp).
 *
 * Vector sources (knsrtp_kat_vectors.h, generated by tools/srtp_reference.py):
 *   - FIPS-197 C.1 and SP800-38A F.1.1: AES-128 block goldens
 *   - RFC 3711 B.2: AES-CM keystream blocks 0,1,2,65279,65280,65281
 *     (the last three exercise the 128-bit counter carry FEFF->FF00)
 *   - RFC 3711 B.3: KDF cipher key (0x00), cipher salt (0x02), 94-octet
 *     auth key (0x01) across six counter blocks with last-block truncation
 *   - cross-implementation goldens (Python reference, nvst.rs semantics):
 *     20B auth key, SRTCP key (0x03), SRTCP salt (0x05), all three IV builders
 * Runs on Linux host and Win7 target. */
#include "kn/kn_aes.h"
#include "kn/kn_sha1.h"
#include "kn/knsrtp.h"
#include "knsrtp_kat_vectors.h"
#include "test_port.h"

#include <stdio.h>
#include <string.h>

static void test_aes_blocks(void)
{
    kn_aes128_ctx ctx;
    uint8_t out[16], buf[16];

    kn_aes128_init(&ctx, k_kat_aes_fips197_key);
    kn_aes128_encrypt(&ctx, k_kat_aes_fips197_pt, out);
    CHECK(memcmp(out, k_kat_aes_fips197_ct, 16) == 0, "FIPS-197 C.1 AES-128 vector");

    /* SP800-38A F.1.1 block 1, in-place (in == out aliasing) */
    memcpy(buf, k_kat_aes_sp80038a_pt, 16);
    kn_aes128_init(&ctx, k_kat_aes_sp80038a_key);
    kn_aes128_encrypt(&ctx, buf, buf);
    CHECK(memcmp(buf, k_kat_aes_sp80038a_ct, 16) == 0, "SP800-38A F.1.1 in-place");
}

static void test_b2_keystream(void)
{
    uint8_t out[16];
    int i;
    for (i = 0; i < 6; ++i) {
        char name[64];
        snprintf(name, sizeof name, "RFC3711 B.2 keystream block idx=%u",
                 k_kat_b2_idx[i]);
        kn_srtp_aes_cm_keystream_block(k_kat_b2_key, k_kat_b2_offset,
                                       k_kat_b2_idx[i], out);
        CHECK(memcmp(out, k_kat_b2_ks[i], 16) == 0, name);
    }
}

static void test_b3_kdf(void)
{
    uint8_t ck[16], cs[14], blk[16], auth[K_KAT_B3_AUTH_KEY_LEN];
    uint8_t a20[20], skey[16], ssalt[14];

    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == 0 &&
          memcmp(ck, k_kat_b3_cipher_key, 16) == 0,
          "B.3 cipher key (label 0x00, 16B)");

    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_SALT, cs, 14) == 0 &&
          memcmp(cs, k_kat_b3_cipher_salt, 14) == 0,
          "B.3 cipher salt (label 0x02, 14B)");

    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_SALT, blk, 16) == 0 &&
          memcmp(blk, k_kat_b3_salt_block0, 16) == 0,
          "B.3 salt label full first block (30CBBC...)");

    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_AUTH_KEY, auth, K_KAT_B3_AUTH_KEY_LEN) == 0 &&
          memcmp(auth, k_kat_b3_auth_key, K_KAT_B3_AUTH_KEY_LEN) == 0,
          "B.3 auth key 94 octets (six blocks + truncation)");

    /* cross-implementation goldens (python reference, nvst.rs semantics) */
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_AUTH_KEY, a20, 20) == 0 &&
          memcmp(a20, k_kat_auth20, 20) == 0,
          "auth key 20B (label 0x01, cross-impl)");
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTCP_LABEL_KEY, skey, 16) == 0 &&
          memcmp(skey, k_kat_srtcp_key, 16) == 0,
          "SRTCP key (label 0x03, cross-impl)");
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTCP_LABEL_SALT, ssalt, 14) == 0 &&
          memcmp(ssalt, k_kat_srtcp_salt, 14) == 0,
          "SRTCP salt (label 0x05, cross-impl)");

    /* 12-byte salt path (GCM profiles derive from 12B master salt) */
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 12,
                         KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == 0,
          "12-byte salt accepted (GCM profile path)");

    /* error paths */
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 15,
                         KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == -1,
          "salt_len > 14 rejected");
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_CIPHER_KEY, ck, 0) == -1,
          "out_len 0 rejected");
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_CIPHER_KEY, NULL, 16) == -1,
          "NULL out rejected");
    CHECK(kn_srtp_kdf128(k_kat_b3_master, NULL, 14,
                         KN_SRTP_LABEL_CIPHER_KEY, ck, 16) == -1,
          "NULL salt rejected");
    CHECK(kn_srtp_kdf128(k_kat_b3_master, k_kat_b3_salt, 14,
                         KN_SRTP_LABEL_CIPHER_KEY, ck, KN_SRTP_MAX_KDF_OUT + 1) == -1,
          "out_len above cap rejected");
}

static void test_iv_builders(void)
{
    uint8_t iv[16], g[12], sg[12];
    uint8_t z14[14];
    int i;

    CHECK(kn_srtp_packet_index(K_KAT_IV_ROC, K_KAT_IV_SEQ) == K_KAT_IV_PKT_INDEX,
          "packet_index = (roc << 16) | seq");

    kn_srtp_aes_cm_iv(k_kat_iv_salt14, K_KAT_IV_SSRC, K_KAT_IV_PKT_INDEX, iv);
    CHECK(memcmp(iv, k_kat_iv_cm, 16) == 0, "SRTP AES-CM IV (nvst.rs:2902)");

    kn_srtp_gcm_iv(k_kat_iv_salt12, K_KAT_IV_SSRC, K_KAT_IV_ROC, K_KAT_IV_SEQ, g);
    CHECK(memcmp(g, k_kat_iv_gcm, 12) == 0, "SRTP GCM IV (RFC 7714 9.1)");

    kn_srtcp_gcm_iv(k_kat_iv_salt12, K_KAT_IV_SSRC, K_KAT_SRTCP_INDEX, sg);
    CHECK(memcmp(sg, k_kat_iv_srtcp_gcm, 12) == 0, "SRTCP GCM IV (RFC 7714 9.2)");

    /* structural placement with zero salt: ssrc at [4..8), index48 at [8..14) */
    memset(z14, 0, sizeof z14);
    kn_srtp_aes_cm_iv(z14, 0xAABBCCDDu, 0x0000112233445566ull, iv);
    CHECK(iv[4] == 0xAA && iv[5] == 0xBB && iv[6] == 0xCC && iv[7] == 0xDD,
          "cm IV ssrc placement");
    CHECK(iv[8] == 0x11 && iv[9] == 0x22 && iv[10] == 0x33 &&
          iv[11] == 0x44 && iv[12] == 0x55 && iv[13] == 0x66,
          "cm IV 48-bit index placement");
    CHECK(iv[14] == 0 && iv[15] == 0, "cm IV tail stays zero");
    for (i = 0; i < 4; ++i)
        CHECK(iv[i] == 0, "cm IV head is salt (zero here)");
}

static void test_keystream_xor(void)
{
    static uint8_t buf[1000], orig[1000], a[1000], b[1000], expect[16];
    int i;

    for (i = 0; i < 1000; ++i) {
        unsigned char v = (unsigned char)(i * 31 + 7);
        buf[i] = v;
        orig[i] = v;
    }

    kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, buf, sizeof buf);
    CHECK(memcmp(buf, orig, sizeof buf) != 0, "keystream xor changes data");

    /* first 16 bytes must equal B.2 block-0 keystream XOR original */
    for (i = 0; i < 16; ++i) expect[i] = (uint8_t)(k_kat_b2_ks[0][i] ^ orig[i]);
    CHECK(memcmp(buf, expect, 16) == 0, "xor matches RFC3711 B.2 block 0");

    /* encrypt/decrypt round-trip (1000 bytes = 62 full blocks + 8-byte tail) */
    kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, buf, sizeof buf);
    CHECK(memcmp(buf, orig, sizeof buf) == 0, "round-trip restores plaintext");

    /* split application must equal continuous: 400 bytes = 25 whole blocks,
     * second chunk resumes at counter block 25 */
    memcpy(a, orig, sizeof a);
    kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, a, sizeof a);
    memcpy(b, orig, sizeof b);
    kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, b, 400);
    kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 25, b + 400, 600);
    CHECK(memcmp(a, b, sizeof a) == 0, "split keystream == continuous (block 25 resume)");

    /* len 0 is a no-op */
    {
        static uint8_t saved[1000];
        memcpy(saved, a, sizeof saved);
        kn_srtp_aes_cm_keystream_xor(k_kat_b2_key, k_kat_b2_offset, 0, a, 0);
        CHECK(memcmp(a, saved, sizeof saved) == 0, "zero-length xor is a no-op");
    }
}


/* ======================= phase 2: SHA-1 / HMAC / auth / replay ============ */

static void test_sha1_kat(void)
{
    uint8_t d[20];
    kn_sha1_ctx c;
    int j;

    kn_sha1("abc", 3, d);
    CHECK(memcmp(d, k_kat_sha1_abc, 20) == 0, "SHA-1 RFC3174 TEST1 (abc)");

    kn_sha1("", 0, d);
    CHECK(memcmp(d, k_kat_sha1_empty, 20) == 0, "SHA-1 empty message");

    kn_sha1(k_kat_sha1_t2_msg, sizeof k_kat_sha1_t2_msg, d);
    CHECK(memcmp(d, k_kat_sha1_t2, 20) == 0, "SHA-1 RFC3174 TEST2 (56B padding edge)");

    /* TEST4: 64-byte base x10 via the streaming API */
    kn_sha1_init(&c);
    for (j = 0; j < 10; ++j)
        kn_sha1_update(&c, k_kat_sha1_t4_msg, sizeof k_kat_sha1_t4_msg);
    kn_sha1_final(&c, d);
    CHECK(memcmp(d, k_kat_sha1_t4, 20) == 0, "SHA-1 RFC3174 TEST4 (streaming)");

    /* TEST3: one million single-byte updates */
    kn_sha1_init(&c);
    for (j = 0; j < 1000000; ++j)
        kn_sha1_update(&c, "a", 1);
    kn_sha1_final(&c, d);
    CHECK(memcmp(d, k_kat_sha1_t3, 20) == 0, "SHA-1 RFC3174 TEST3 (1M x 'a')");
}

static void test_hmac_kat(void)
{
    uint8_t d[20];
    int i;
    for (i = 0; i < 7; ++i) {
        char name[48];
        snprintf(name, sizeof name, "HMAC-SHA1 RFC2202 case %d", i + 1);
        kn_hmac_sha1(k_kat_hmac_blob + k_kat_hmac_key_off[i],
                     k_kat_hmac_key_len[i],
                     k_kat_hmac_blob + k_kat_hmac_data_off[i],
                     k_kat_hmac_data_len[i], d);
        CHECK(memcmp(d, k_kat_hmac_digest[i], 20) == 0, name);
    }
    /* incremental API must equal one-shot (case 1, split mid-message) */
    {
        kn_hmac_sha1_ctx hc;
        kn_hmac_sha1_init(&hc, k_kat_hmac_blob + k_kat_hmac_key_off[0],
                          k_kat_hmac_key_len[0]);
        kn_hmac_sha1_update(&hc, "Hi ", 3);
        kn_hmac_sha1_update(&hc, "There", 5);
        kn_hmac_sha1_final(&hc, d);
        CHECK(memcmp(d, k_kat_hmac_digest[0], 20) == 0,
              "incremental HMAC == one-shot (case 1)");
    }
}

static void test_ct_memeq(void)
{
    uint8_t a[10], b[10];
    memset(a, 0x42, sizeof a);
    memcpy(b, a, sizeof b);
    CHECK(kn_ct_memeq(a, b, sizeof a) == 1, "ct_memeq equal");
    b[9] ^= 0xFF;
    CHECK(kn_ct_memeq(a, b, sizeof a) == 0, "ct_memeq differs at last byte");
    CHECK(kn_ct_memeq(a, b, 0) == 1, "ct_memeq zero length");
}

static void test_p2_protect_unprotect(void)
{
    uint8_t pkt[128];
    size_t plain_len = 0;
    int rc;
    const uint8_t *enc = k_kat_b3_cipher_key;    /* == derived session enc key */
    const uint8_t *csalt = k_kat_b3_cipher_salt; /* == derived session salt    */
    const uint8_t *auth = k_kat_auth20;          /* == derived auth key (20B)  */

    /* protect -> byte-identical to the python golden (ciphertext + tag80) */
    memcpy(pkt, k_kat_p2_plain, K_KAT_P2_PLAIN_LEN);
    rc = kn_srtp_protect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN, K_KAT_P2_PAYLOAD_OFF,
                                 K_KAT_P2_SSRC, K_KAT_P2_PKT_INDEX, enc, auth,
                                 csalt, KN_SRTP_TAG_LEN_80);
    CHECK(rc == 0, "protect rc");
    CHECK(memcmp(pkt, k_kat_p2_protected10,
                 K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80) == 0,
          "protect matches golden (tag 80)");

    /* unprotect round-trip */
    rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                   K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                   K_KAT_P2_PKT_INDEX, enc, auth,
                                   csalt, KN_SRTP_TAG_LEN_80, &plain_len);
    CHECK(rc == 0 && plain_len == K_KAT_P2_PLAIN_LEN, "unprotect rc + plain_len");
    CHECK(memcmp(pkt, k_kat_p2_plain, K_KAT_P2_PLAIN_LEN) == 0,
          "unprotect restores plaintext");

    /* tag-32 variant */
    memcpy(pkt, k_kat_p2_plain, K_KAT_P2_PLAIN_LEN);
    rc = kn_srtp_protect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN, K_KAT_P2_PAYLOAD_OFF,
                                 K_KAT_P2_SSRC, K_KAT_P2_PKT_INDEX, enc, auth,
                                 csalt, KN_SRTP_TAG_LEN_32);
    CHECK(rc == 0 && memcmp(pkt, k_kat_p2_protected4,
                            K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_32) == 0,
          "protect matches golden (tag 32)");

    /* tamper with a ciphertext byte -> auth fail, buffer untouched
     * (authenticate-before-decrypt, nvst.rs order) */
    memcpy(pkt, k_kat_p2_protected10, sizeof k_kat_p2_protected10);
    pkt[20] ^= 0xFF;
    {
        uint8_t saved[128];
        memcpy(saved, pkt, sizeof k_kat_p2_protected10);
        rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                       K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                       K_KAT_P2_PKT_INDEX, enc, auth, csalt, KN_SRTP_TAG_LEN_80,
                                       &plain_len);
        CHECK(rc == 1, "tampered payload -> AuthenticationFailed");
        CHECK(memcmp(pkt, saved, sizeof k_kat_p2_protected10) == 0,
              "failed auth leaves packet untouched");
    }

    /* tamper with the tag itself */
    memcpy(pkt, k_kat_p2_protected10, sizeof k_kat_p2_protected10);
    pkt[K_KAT_P2_PLAIN_LEN + 3] ^= 0x01;
    rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                   K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                   K_KAT_P2_PKT_INDEX, enc, auth,
                                   csalt, KN_SRTP_TAG_LEN_80, &plain_len);
    CHECK(rc == 1, "tampered tag -> AuthenticationFailed");

    /* malformed / invalid args */
    memcpy(pkt, k_kat_p2_protected10, sizeof k_kat_p2_protected10);
    rc = kn_srtp_unprotect_cm_hmac(pkt, 9, K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                   K_KAT_P2_PKT_INDEX, enc, auth,
                                   csalt, KN_SRTP_TAG_LEN_80, &plain_len);
    CHECK(rc == -1, "packet shorter than tag -> -1");
    rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                   K_KAT_P2_PLAIN_LEN + 1, K_KAT_P2_SSRC,
                                   K_KAT_P2_PKT_INDEX, enc, auth,
                                   csalt, KN_SRTP_TAG_LEN_80, &plain_len);
    CHECK(rc == -1, "payload_offset beyond authenticated part -> -1");
    rc = kn_srtp_unprotect_cm_hmac(pkt, K_KAT_P2_PLAIN_LEN + KN_SRTP_TAG_LEN_80,
                                   K_KAT_P2_PAYLOAD_OFF, K_KAT_P2_SSRC,
                                   K_KAT_P2_PKT_INDEX, enc, auth,
                                   csalt, 5, &plain_len);
    CHECK(rc == -1, "invalid tag_len -> -1");
    rc = kn_srtp_protect_cm_hmac(pkt, 10, 11, K_KAT_P2_SSRC, 1, enc, auth,
                                 csalt, KN_SRTP_TAG_LEN_80);
    CHECK(rc == -1, "protect payload_offset > plain_len -> -1");

    /* roc helper */
    CHECK(kn_srtp_roc_of(0x11234ull) == 1, "roc_of(0x11234) == 1");
    CHECK(kn_srtp_roc_of(0xFFFFull) == 0, "roc_of(0xFFFF) == 0");
    CHECK(kn_srtp_roc_of(0x100000005ull) == 0x10000u, "roc_of 40-bit index");
}

static void test_replay_vectors(void)
{
    kn_srtp_replay w;
    int i, mism = 0, first_bad = -1;
    kn_srtp_replay_init(&w);
    for (i = 0; i < K_KAT_REPLAY_N; ++i) {
        uint64_t idx = 0;
        int grc = kn_srtp_replay_guess(&w, k_kat_replay_seq[i], &idx);
        if (grc != (int)k_kat_replay_guess_rc[i]) {
            mism++; if (first_bad < 0) first_bad = i; continue;
        }
        if (grc != 0) continue;
        if (idx != k_kat_replay_index[i]) {
            mism++; if (first_bad < 0) first_bad = i; continue;
        }
        {
            int crc = kn_srtp_replay_check(&w, idx);
            if (crc != (int)k_kat_replay_check_rc[i]) {
                mism++; if (first_bad < 0) first_bad = i; continue;
            }
            if (crc == 0) kn_srtp_replay_commit(&w, idx);
        }
    }
    if (mism) printf("  replay mismatches=%d first at op %d\n", mism, first_bad);
    CHECK(mism == 0, "replay window == reference simulation (96 ops, all branches)");
}

static void test_replay_edges(void)
{
    kn_srtp_replay w;
    uint64_t idx;

    kn_srtp_replay_init(&w);
    CHECK(kn_srtp_replay_check(&w, 12345) == 0, "cold window accepts anything");
    CHECK(kn_srtp_replay_guess(&w, 7, &idx) == 0 && idx == 7,
          "cold guess = seq (no roc history)");
    kn_srtp_replay_commit(&w, 300000);
    CHECK(kn_srtp_replay_check(&w, 300000) == 1, "exact duplicate rejected");
    CHECK(kn_srtp_replay_check(&w, 299999) == 0, "age 1 unseen accepted");
    kn_srtp_replay_commit(&w, 299999);
    CHECK(kn_srtp_replay_check(&w, 299999) == 1, "committed late packet now rejected");
    CHECK(kn_srtp_replay_check(&w, 300000 - 2047) == 0, "age 2047 inside window");
    CHECK(kn_srtp_replay_check(&w, 300000 - 2048) == 1, "age 2048 outside window");

    /* defensive: commit of an out-of-window index must be a no-op, not UB */
    kn_srtp_replay_commit(&w, 300000 - 3000);
    CHECK(kn_srtp_replay_check(&w, 299998) == 0,
          "out-of-window commit did not corrupt the window");
}

int main(void)
{
    test_aes_blocks();
    test_b2_keystream();
    test_b3_kdf();
    test_iv_builders();
    test_keystream_xor();
    test_sha1_kat();
    test_hmac_kat();
    test_ct_memeq();
    test_p2_protect_unprotect();
    test_replay_vectors();
    test_replay_edges();
    return kn_test_summary("test_knsrtp");
}
